'figeac|2021':{blend:{ME:29,CF:31,CS:40},yld:40,window:'Contrairement au passé, même les très jeunes millésimes sont agréables à boire.',url:'https://www.chateau-figeac.com/millesime/millesime-2021/',src:'CHATEAU-FIGEAC-Datasheet-March-2021.pdf'},
