'giscours|2021':{blend:{CS:56,ME:44},url:'https://giscours.com/fr/2021/08/16/rose-x-giscours-2020-la-nouvelle-signature-du-chateau-giscours/',src:'2021__07-02-millesime-2020-du-chateau-giscours-precision-et-audace.txt'},
'gruaud-larose|2019':{blend:{ME:72,CF:25},note:'MERLOT CABERNET SAUVIGNON CABERNET FRANC PETIT VERDOT Pointes vertes 15-mars 29-mars 15-mars 29-mars Début floraison 24-mai 01-juin 25-mai 24-mai Début véraison 26-juil 26-juil 27-juil 27-juil DATES DE RECOLTE 20-sept au 25-sept 26-sept au 08-oct 30-sept au 01-oct 5-oct.',taste:'Two threatening frost episodes in April in the end had very little effect on the Gruaud vineyard, which benefited from its closeness to the Gironde.',src:'chateau-gruaud-larose-2019-fr.pdf',ttl:1},
'gruaud-larose|2022':{blend:{ME:83,CF:14},harvest:'7 Septembre',note:'Coming out of a mild and moderately wet winter, the Merlot parcels at the foot of the rises were exposed to a serious frost episode during the first ten days of April.',src:'Chateau-Gruaud-Larose-2022-FR.pdf',ntl:1},
'gruaud-larose|2023':{blend:{ME:64,CF:30,PV:4},note:'Through the winter the cover crops are grazed by a flock of 300 ewes.',src:'Chateau-Gruaud-Larose-2023-FR.pdf',ntl:1},
'gruaud-larose|2024':{blend:{ME:64,CF:30,PV:4},harvest:'27 septembre',ph:3.77,src:'Chateau-Gruaud-Larose-2024-FR.pdf'},
'guiraud|2022':{harvest:'15 septembre',yld:10,ph:4.01,window:'Finale très longue présageant du beau potentiel de garde de ce vin !',note:'After a mild winter, the 2022 growing season began very early.',taste:'A very long finish, promising fine ageing potential for this wine.',src:'cha-teau-guiraud-1er-grand-cru-classe-en-1855-2022.pdf',ttl:1,ntl:1},
'guiraud|2023':{blend:{SEM:60,SB:40},harvest:'24 août',yld:30,ph:3.4,note:'A warm vintage on the whole, with very contrasting rainfall. After a frost episode at the very start of April, the vine\'s growth began in ideal conditions: warmth and regular rainy spells produced an exuberant canopy that called for all our growers\' commitment and expertise to keep in check.',taste:'www.chateauguiraud.com @châteauguiraud 1 Château Guiraud, 33210 Sauternes Chateau Guiraud Chateau Guiraud RATINGS Yves Beck : 92-93 /100 90 /100 Bettane & Desseauve :',src:'g-de-chateau-guiraud-2023_fr.pdf',ntl:1},
