'la-tour-carnet|2018':{blend:{CS:54,ME:44,PV:1,CF:1},url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2018/',src:'2018__products-chateau-pape-clement-rouge-2018.txt'},
'la-tour-carnet|2019':{blend:{ME:90,CF:10},harvest:'du 18 septembre au 11 octobre 2019',url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2019/',src:'2019__products-chateau-fombrauge-rouge-2019.txt'},
'la-tour-carnet|2020':{blend:{ME:96,CF:4},url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2020/',src:'2020__products-chateau-fombrauge-rouge-2020.txt'},
'la-tour-carnet|2021':{blend:{ME:60,CS:40},harvest:'du 28 septembre au 14 octobre 2021',url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2021/',src:'2021__products-chateau-fombrauge-rouge-2021.txt'},
