'pape-clement|2015':{blend:{ME:95,CF:5},alc:14.5,url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2015/',src:'2015__products-chateau-fombrauge-rouge-2015.txt'},
'pape-clement|2016':{blend:{ME:93,CF:7},url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2016/',src:'2016__products-chateau-fombrauge-rouge-2016.txt'},
'pape-clement|2017':{blend:{SEM:95,SB:5},url:'https://bernard-magrez.com/products/clos-haut-peyraguey-2017/',src:'2017__products-clos-haut-peyraguey-2017.txt'},
'pape-clement|2018':{blend:{CS:54,ME:44,PV:1,CF:1},url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2018/',src:'2018__products-chateau-pape-clement-rouge-2018.txt'},
'pape-clement|2019':{blend:{ME:90,CF:10},harvest:'du 18 septembre au 11 octobre 2019',url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2019/',src:'2019__products-chateau-fombrauge-rouge-2019.txt'},
'pape-clement|2020':{blend:{ME:96,CF:4},url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2020/',src:'2020__products-chateau-fombrauge-rouge-2020.txt'},
'pape-clement|2021':{blend:{ME:60,CS:40},harvest:'du 28 septembre au 14 octobre 2021',url:'https://bernard-magrez.com/products/chateau-pape-clement-rouge-2021/',src:'2021__products-chateau-fombrauge-rouge-2021.txt'},
